#!/usr/bin/env bash\nset -e\n\n# Mock rationale: This script runs terraform init and validate to ensure the module syntax is correct.\n# It then applies the module with auto-approve and checks that weather.json is created.\n\ncd "$(dirname "$0")/.."\n\nterraform init -backend=false -input=false > /dev/null\n\nterraform validate -no-color\n\nterraform apply -auto-approve -input=false > /dev/null\n\nif [[ -f "weather.json" ]]; then\n  echo "Test passed: weather.json created"\n  exit 0\nelse\n  echo "Test failed: weather.json not found"\n  exit 1\nfi\n
